const COMMON_LIMITATIONS = [
  'Hipóteses editoriais a validar, sem classificação de intensidade das forças, pontuação de risco ou diagnóstico do cliente.',
  'Não houve validação empírica desta ficha nem leitura direta das páginas institucionais listadas nesta redação. Os links são referências para pesquisa, não evidências que confirmem os mecanismos.',
  'Faltam dados de mercado delimitado, contratos e operação do cliente. A data é da revisão editorial; não é atualização de notícias ou indicadores.',
  'Equivalentes nacionais, importados ou vendidos por outro canal integram a rivalidade; candidatos ainda não aptos à oferta podem ser entrantes. Substitutos exigem outra solução fora do mercado delimitado, não apenas troca de vendedor.',
  'Custo alto, volatilidade ou falta de capacidade não provam poder de fornecedor: verificar concentração, exclusividade, dependência técnica, custo de troca e condições efetivamente negociáveis.',
]

function profile(id, scope, forces, questions, points, sourceKeys, scopeNote) {
  return {
    id,
    scope,
    reviewedAt: '2026-11-05',
    analysisKind: 'hipoteses-editoriais',
    scopeNote: scopeNote || 'Delimitar a praça, o produto e o público atendido antes de aplicar as hipóteses. Não extrapolar para todos os elos da cadeia.',
    forces: forces.map(([mechanism, validateWith], i) => ({
      id: FORCE_IDS[i],
      mechanism: `Hipótese a validar: ${mechanism}`,
      validateWith,
    })),
    sensitivePoints: points.map(([title, signal], i) => ({ id: `${id}-p${i + 1}`, title, signal, questionIndex: i })),
    questions,
    sources: sourceKeys.map(key => ({ ...SOURCES[key] })),
    limitations: [...COMMON_LIMITATIONS],
  }
}

